solid(-4,-5,5,1.4,1.25);solid(5,8,4,1.5,1.2);solid(3,-18,3,3,2.4);solid(-15,18,4,1.5,1.2);
for(const p of [[-4,-5,5],[5,8,4],[-15,18,4]]){box(staticData,p[0],1.15,p[1]+.72,p[2]-.12,.12,.04,palettes.lime,1);}
box(staticData,0,.01,-.5,4,.02,4,[.34,.39,.35]);
