box(staticData,0,9,-27,45,.7,1,palettes.dark);box(staticData,0,8.5,-26.9,5,2,.4,palettes.dark);box(staticData,0,8.6,-26.66,3.7,.1,.05,palettes.lime,1);
// Background skyline, deterministic geometry.
for(let i=0;i<44;i++){let a=i*2.39996,r=45+(i%4)*9,h=8+(i*17%31),x=Math.sin(a)*r,z=Math.cos(a)*r;box(staticData,x,h/2,z,5+i%5,h,5+i%3,[.25+(i%3)*.03,.33,.35]);for(let y=4;y<h;y+=3.5)box(staticData,x,y,z+3+i%3/2,3,.08,.04,[.52,.64,.61],1);box(staticData,x,h+1,z,.15,2,.15,palettes.dark);}
