  const yaw=.09+presentation*.42,cy=Math.cos(yaw),sy=Math.sin(yaw),roll=-.035-reloadDip*.19+presentation*.70,cr=Math.cos(roll),sr=Math.sin(roll),m=akViewMatrix;
