  m[4]=-sr*cp+sy*cr*sp;m[5]=cr*cp+sy*sr*sp;m[6]=cy*sp;m[7]=0;
  m[8]=sr*sp+sy*cr*cp;m[9]=-cr*sp+sy*sr*cp;m[10]=cy*cp;m[11]=0;
  m[12]=rx;m[13]=ry;m[14]=rz;m[15]=1;
