  out[4]=m[4]*h;out[5]=m[5]*h;out[6]=m[6]*h;out[7]=0;
  out[8]=m[8]*d;out[9]=m[9]*d;out[10]=m[10]*d;out[11]=0;
  out[12]=m[0]*x+m[4]*y+m[8]*z+m[12];
