    knifeQuad(out,p(inner,a,-1),p(inner,b,-1),p(outer,b,-1),p(outer,a,-1),color);
    knifeQuad(out,p(outer,a,-1),p(outer,b,-1),p(outer,b,1),p(outer,a,1),color);
