  const y=-.44-1.20*hide+.08*swing-.15*wind-Math.abs(Math.cos(b))*.007*moving;
  const z=-.96+.04*hide-.11*swing;
  const roll=.58-1.45*hide+1.35*sweep-.60*wind;
